

def build_iperf_client_command(server_ip, bitrate, transmission_time, interval=1,
                               bind_interface=None, udp=False, port=None,
                               buf_length=None):
    """
    Builds iperf Client command.

    :param server_ip: iperf server ip
    :param bitrate: target bitrate in format n[KM] where n is number
    :param transmission_time: time in second to transmit for
    :param interval:  Specify pause between periodic throughput reports. 0 - disables. Default 1.
    :param bind_interface:  interface to bind. (optional)
    :param udp: set true to use udp. Default false.
    :param port: iperf port. (optional)
    :param buf_length: length of read/write buffer (optional)
    """
    cmd_tpl = "echo $$; exec iperf -c {server_ip} -t {transmission_time} -b {bitrate} -i {interval}"
    cmd = cmd_tpl.format(server_ip=server_ip,
                         transmission_time=transmission_time, bitrate=bitrate,
                         interval=interval)
    if bind_interface:
        cmd = cmd + " -B {bind_interface}".format(bind_interface=bind_interface)
    if port:
        cmd = cmd + " -p {port}".format(port=port)
    if buf_length:
        cmd = cmd + " -l {buf_length}".format(buf_length=buf_length)
    if udp:
        cmd = cmd + " -u"
    cmd = cmd + " 1>/dev/null 2>/dev/null"
    return cmd
